{
    "$schema": "http://json-schema.org/draft-04/schema#",
    "title": "Bleep Client Config",
    "description": "Client config that defines variables that are used for Bleep connection, these are provided with generate tokens response",
    "type": "object",
    "properties": {
        "soft_timeout_ms": {
            "description": "Represents soft timeout time in milliseconds",
            "type": "integer",
            "minimum": 0,
            "exclusiveMinimum": true
        },
        "server_switch_max_wait_connection_seconds": {
            "description": "Represents max wait time for connection to server before another server switch is performed",
            "type": "number",
            "minimum": 0,
            "exclusiveMinimum": true
        },
        "server_switch_max_retries": {
            "description": "Represents the max amount of server switches that are allowed to be performed",
            "type": "integer",
            "minimum": 0,
            "exclusiveMinimum": true
        },
        "first_connect_failure_initial_wait_ms": {
            "description": "Represents the initial wait time in milliseconds for initial connection to a server when game is first starting",
            "type" : "integer",
            "minimum": 0,
            "exclusiveMinimum": true
        },
        "first_connect_failure_direct_wait_ms": {
            "description": "Represents the wait time in milliseconds for initial connection to a server before client tries to connect directly to instance server",
            "type": "integer",
            "minimum": 0,
            "exclusiveMinimum": true
        },
        "first_connect_failure_next_server_wait_ms": {
            "description": "Represents the wait time in milliseconds for initial connection to a server before trying the next server in server list client has cached",
            "type": "integer",
            "minimum": 0,
            "exclusiveMinimum": true
        }
    }
    }

).  Note that the exact same class is required; not just the same descriptor.	ascii
